return-response.set-body:
@{
                var gatewayUrl = "{{APIMGatewayURL}}";
                var tenantId = "{{McpTenantId}}";
                var clientId = "{{McpClientId}}";

                var prm = new JObject
                {
                    ["resource"] = gatewayUrl,
                    ["authorization_servers"] = new JArray
                    {
                        new JObject
                        {
                            ["authorization_endpoint"] = $"https://login.microsoftonline.com/{tenantId}/oauth2/v2.0/authorize",
                            ["token_endpoint"] = $"https://login.microsoftonline.com/{tenantId}/oauth2/v2.0/token",
                            ["scopes_supported"] = new JArray { $"api://{clientId}/user_impersonate" },
                            ["response_types_supported"] = new JArray { "code" },
                            ["grant_types_supported"] = new JArray { "authorization_code" },
                            ["token_endpoint_auth_methods_supported"] = new JArray { "none" },
                            ["code_challenge_methods_supported"] = new JArray { "S256" }
                        }
                    }
                };

                return prm.ToString();
            }
